// An invented HTTP client, declared the way a `create({ baseURL })` client
// is: a callable default export with verb members, a config-object request
// member, and a factory whose options name the base URL.

export type Method =
  | "GET"
  | "POST"
  | "PUT"
  | "PATCH"
  | "DELETE"
  | "get"
  | "post"
  | "put"
  | "patch"
  | "delete";

export interface RequestConfig<D = unknown> {
  url?: string;
  method?: Method;
  data?: D;
  headers?: Record<string, string>;
  timeout?: number;
}

export interface CreateOptions {
  baseURL?: string;
  headers?: Record<string, string>;
  timeout?: number;
}

export interface HttpResponse<T> {
  data: T;
  status: number;
}

export interface HttpInstance {
  <T = unknown, D = unknown>(config: RequestConfig<D>): Promise<HttpResponse<T>>;
  request<T = unknown, D = unknown>(config: RequestConfig<D>): Promise<HttpResponse<T>>;
  get<T = unknown>(url: string, config?: RequestConfig): Promise<HttpResponse<T>>;
  post<T = unknown, D = unknown>(
    url: string,
    data?: D,
    config?: RequestConfig<D>,
  ): Promise<HttpResponse<T>>;
}

export interface HttpStatic extends HttpInstance {
  create(options?: CreateOptions): HttpInstance;
}

declare const http: HttpStatic;
export default http;
